from __future__ import annotations

import sys

if sys.version_info &gt;= (3, 11):
    from enum import StrEnum
    from typing import Self, override
else:
    from backports.strenum import StrEnum
    from typing_extensions import Self, override


class CaseInsensitiveStrEnum(StrEnum):
    """A case-insensitive string enum.

    This class extends the `StrEnum` class to provide case-insensitive member lookup.
    It also provides a custom `_generate_next_value_` method that returns the
    lowercase version of the member name for use with `auto()`.
    """

    @classmethod
    def __init_subclass__(cls, **kwargs: dict[str, Any]) -&gt; None:
        """Implement the special hook that is called when a class is subclassed.

        It allows us to customize the class creation process without using metaclasses.
        """
        super().__init_subclass__(**kwargs)

        for member in cls:
            if not member.islower() or not member.value.islower():
                msg = f"Member '{member}' and value {member.value} must be lowercase."
                raise TypeError(msg)

    @override
    @staticmethod
    def _generate_next_value_(
        name: str, start: int, count: int, last_values: list[str]
    ) -&gt; str:
        """Return the lower-cased version of the member name.

        This method is overridden to ensure that when `auto()` is used to create
        enum members, their values are the lowercase version of their names.
        """
        return name.lower()

    @override
    @classmethod
    def _missing_(cls, value: object) -&gt; Self | None:
        """Provide case-insensitive member lookup.

        This method is called when a value is not found in the enum.
        It is overridden to perform a case-insensitive search for the member.
        """
        if not isinstance(value, str):
            return None

        value = value.lower()
        for member in cls:
            if member.name.lower() == value:
                return member

        return None

The Property Decorator: @property
In finance, invalid data can lead to significant errors. A negative strike price or a negative volatility is nonsensical. In languages like Java or C++, you typically implement getStrike() and setStrike() methods to handle validation. Python offers a cleaner alternative: the @property decorator.
This allows us to access a method as if it were an attribute, adding logic like validation seamlessly.


Show the code
class EuropeanOption:
    def __init__(self, strike: float):
        # We assign to the property, triggering the setter validation
        self.strike = strike

    @property
    def strike(self):
        return self._strike

    @strike.setter
    def strike(self, value):
        if value &lt; 0:
            raise ValueError("Strike price cannot be negative.")
        self._strike = value

opt = EuropeanOption(100)
print(f"Current Strike: {opt.strike}")

try:
    opt.strike = -50
except ValueError as e:
    print(f"Error caught: {e}")


Current Strike: 100
Error caught: Strike price cannot be negative.


Notice we use self._strike inside the property to store the actual value.

Concrete Implementations
With the ground rules established, let’s build something real. The simplest case is a Flat Forward Curve, where the rate is constant forever.


